#' Launch the locusmatch web application
#'
#' A three-step workflow:
#'
#' 1. **Earlier studies.** Pick the reference GWAS from Open Targets, either
#'    by trait (search, then choose among that trait's studies) or by pasting
#'    a list of accessions, narrow them down with filters (years, ancestry,
#'    study kind, number of cases) and tick or untick individual studies; or
#'    upload your own credible sets.
#' 2. **Your GWAS.** Upload its credible sets (optionally its thinned summary
#'    statistics), or pick one of the Open Targets studies as the query.
#' 3. **Results.** Interactive signal map, classification tables, downloads.
#'
#' Starts with the simulated [lm_example] data loaded, so every tab works
#' before anything is uploaded.
#'
#' @param ... Passed to [shiny::shinyApp()] options, e.g. `port`.
#' @examples
#' if (interactive()) lm_app()
#' @export
lm_app <- function(...) {
  for (p in c("shiny", "bslib", "ggiraph", "DT")) {
    if (!requireNamespace(p, quietly = TRUE)) stop("install ", p, " to run the app")
  }
  shiny::shinyApp(app_ui(), app_server, options = list(...))
}

read_table_input <- function(f) {
  if (is.null(f)) return(NULL)
  data.table::fread(f$datapath)
}

parse_accessions <- function(text) {
  x <- unlist(strsplit(text %||% "", "[\\s,;]+", perl = TRUE))
  unique(x[nzchar(x)])
}

KIND_LABELS <- c(primary = "Primary GWAS of the trait", multi_trait = "Multi-trait / cross-disorder",
                 mtag = "MTAG", family_history = "Family history (proxy)",
                 interaction = "Interaction scans", case_case = "Case-case",
                 treatment_response = "Treatment response")
KIND_SHORT <- c(primary = "primary", multi_trait = "multi-trait", mtag = "MTAG",
                family_history = "family history", interaction = "interaction",
                case_case = "case-case", treatment_response = "treatment response")

# "nfe 0.80; eas 0.20" -> "nfe 80%, eas 20%"; a single population is shown alone
format_ancestry <- function(x) {
  vapply(strsplit(ifelse(is.na(x), "", x), "; ", fixed = TRUE), function(parts) {
    if (!length(parts) || identical(parts, "")) return("")
    pop <- sub(" .*", "", parts)
    frac <- suppressWarnings(as.numeric(sub(".* ", "", parts)))
    if (length(pop) == 1) return(pop)
    paste(sprintf("%s %.0f%%", pop, 100 * frac), collapse = ", ")
  }, character(1))
}

# Selected rows: a light tint and a left bar instead of DataTables' solid blue.
STUDY_TABLE_CSS <- "
#study_table table.dataTable tbody tr.selected > * {
  box-shadow: inset 0 0 0 9999px rgba(42, 120, 214, 0.10) !important; color: inherit !important; }
#study_table table.dataTable tbody tr.selected > td:first-child {
  border-left: 3px solid #2a78d6; }
#study_table table.dataTable tbody tr.selected a { color: #1d5fae !important; }
#study_table table.dataTable td.dt-nowrap { white-space: nowrap; }
#study_table table.dataTable { font-size: 0.875rem; }
"

ANCESTRY_LABELS <- c(nfe = "European (nfe)", fin = "Finnish (fin)", eas = "East Asian (eas)",
                     sas = "South Asian (sas)", afr = "African (afr)", amr = "Admixed American (amr)",
                     asj = "Ashkenazi (asj)", mid = "Middle Eastern (mid)", oth = "Other (oth)")

STUDY_COLUMNS <- c(Study = "label", Year = "year", Trait = "trait", Kind = "kind",
                   Cases = "n_cases", N = "n", Ancestry = "ancestry",
                   `Credible sets` = "n_credible_sets", Sumstats = "has_sumstats",
                   Accession = "study_id")

app_ui <- function() {
  help <- function(...) shiny::tags$small(class = "text-muted d-block mb-2", ...)
  bslib::page_navbar(
    id = "navbar",
    title = "locusmatch",
    theme = bslib::bs_theme(version = 5, bg = "#fcfcfb", fg = "#0b0b0b", primary = "#2a78d6",
                            base_font = bslib::font_collection("system-ui", "sans-serif")),
    bslib::nav_panel(
      "1. Earlier studies",
      bslib::layout_sidebar(
        sidebar = bslib::sidebar(
          width = 340,
          shiny::radioButtons("ref_mode", "Find earlier studies", c(
            "By trait" = "trait", "By accession list" = "accession", "Upload my own" = "upload")),
          shiny::conditionalPanel(
            "input.ref_mode == 'trait'",
            shiny::div(class = "d-flex gap-2 align-items-end",
                       shiny::textInput("trait_text", "Trait", placeholder = "e.g. schizophrenia"),
                       shiny::actionButton("trait_search", "Search", class = "btn-sm mb-3")),
            shiny::selectInput("trait_pick", NULL, choices = NULL, multiple = TRUE),
            shiny::checkboxInput("trait_descendants", "Include subtypes (descendant terms)", FALSE)
          ),
          shiny::conditionalPanel(
            "input.ref_mode == 'accession'",
            shiny::textAreaInput("accessions", "Accessions", rows = 5,
                                 placeholder = "GCST90128471\nGCST002539\nFINNGEN_R12_F5_SCHZPHR"),
            help("GWAS Catalog (GCST...), FinnGen and UK Biobank study IDs, one per line or comma-separated.")
          ),
          shiny::conditionalPanel(
            "input.ref_mode != 'upload'",
            shiny::actionButton("list_studies", "List studies", class = "btn-primary"),
            shiny::hr(),
            shiny::tags$b("Filters"),
            shiny::sliderInput("f_years", "Publication years", 2005, 2026, c(2005, 2026), step = 1, sep = ""),
            shiny::checkboxGroupInput("f_kinds", "Study kinds", choices = stats::setNames(names(KIND_LABELS), KIND_LABELS),
                                      selected = "primary"),
            shiny::checkboxGroupInput("f_ancestry", "Ancestry (LD population)", choices = NULL),
            shiny::selectInput("f_anc_match", NULL, c("largest population matches" = "main",
                                                      "any population matches" = "any",
                                                      "all populations match" = "only")),
            shiny::numericInput("f_min_cases", "Minimum cases", 0, min = 0, step = 500),
            shiny::checkboxInput("f_need_cs", "Only studies with credible sets", TRUE)
          ),
          shiny::conditionalPanel(
            "input.ref_mode == 'upload'",
            shiny::fileInput("ref_cs", "Credible sets"),
            help("cs_id, study_id, chrom, pos, variant_id, pip; optional lbf, in_cs, p"),
            shiny::fileInput("ref_studies", "Study table"),
            help("study_id, pub_date, optional label")
          )
        ),
        shiny::tags$style(STUDY_TABLE_CSS),
        shiny::div(class = "d-flex flex-wrap gap-2 align-items-center mb-2",
                   shiny::actionButton("fetch", "Use selected studies", class = "btn-primary btn-sm"),
                   shiny::actionButton("sel_all", "Select all", class = "btn-sm btn-outline-secondary"),
                   shiny::actionButton("sel_none", "Select none", class = "btn-sm btn-outline-secondary"),
                   shiny::uiOutput("study_status", inline = TRUE)),
        DT::DTOutput("study_table")
      )
    ),
    bslib::nav_panel(
      "2. Your GWAS",
      bslib::layout_columns(
        col_widths = c(5, 7),
        bslib::card(
          shiny::radioButtons("query_mode", "Your GWAS", c(
            "Upload its credible sets" = "upload",
            "One of the Open Targets studies loaded in step 1" = "ot",
            "Demo (simulated data)" = "demo"), selected = "demo"),
          shiny::conditionalPanel(
            "input.query_mode == 'upload'",
            shiny::fileInput("query_cs", "Credible sets"),
            help("Same columns as the reference; an optional 'gene' column labels the figure."),
            shiny::textInput("query_label", "Label", "This study"),
            shiny::dateInput("query_date", "Date", Sys.Date())
          ),
          shiny::conditionalPanel(
            "input.query_mode == 'ot'",
            shiny::selectInput("query_study", "Study", choices = NULL)
          ),
          shiny::conditionalPanel(
            "input.query_mode != 'demo'",
            shiny::fileInput("query_sumstats", "Thinned summary statistics (optional)"),
            help("chrom, pos, p. Drawn in grey under the signals."),
            shiny::fileInput("blocks", "LD blocks, BED (optional)"),
            help("Without a file, evenly spaced 1.5 Mb blocks are used.")
          ),
          shiny::sliderInput("t_h4", "Same signal if H4 \u2265", 0.5, 0.99, 0.8, 0.01),
          shiny::sliderInput("t_h3", "Distinct signal if H3 \u2265", 0.5, 0.99, 0.8, 0.01),
          shiny::actionButton("run", "Compare", class = "btn-primary")
        ),
        bslib::card(bslib::card_header("Reference loaded"), shiny::uiOutput("ref_summary"))
      )
    ),
    bslib::nav_panel(
      "3. Signal map",
      shiny::uiOutput("summary"),
      ggiraph::girafeOutput("map", height = "auto"),
      shiny::div(class = "d-flex gap-2",
                 shiny::downloadButton("dl_png", "Figure (PNG, 300 dpi)", class = "btn-sm"),
                 shiny::downloadButton("dl_pdf", "Figure (PDF)", class = "btn-sm"))
    ),
    bslib::nav_panel("Your signals", DT::DTOutput("calls"),
                     shiny::downloadButton("dl_calls", "Download TSV", class = "btn-sm")),
    bslib::nav_panel("Signal registry", DT::DTOutput("signals"),
                     shiny::downloadButton("dl_signals", "Download TSV", class = "btn-sm")),
    bslib::nav_panel("How to read the map", shiny::markdown(HOW_TO_READ))
  )
}

app_server <- function(input, output, session) {
  rv <- shiny::reactiveValues(studies = NULL, ref = NULL)
  notify_error <- function(expr) tryCatch(expr, error = function(e) {
    shiny::showNotification(conditionMessage(e), type = "error", duration = 10)
    NULL
  })

  # ---- step 1: find and filter earlier studies --------------------------------
  shiny::observeEvent(input$trait_search, {
    hits <- notify_error(ot_search_traits(input$trait_text, n = 10))
    if (is.null(hits) || !nrow(hits)) return()
    hits <- hits[n_studies > 0]
    shiny::updateSelectInput(session, "trait_pick", selected = hits$trait_id[1], choices = stats::setNames(
      hits$trait_id, sprintf("%s (%s), %d GWAS", hits$name, hits$trait_id, hits$n_studies)))
  })

  shiny::observeEvent(input$list_studies, {
    st <- notify_error(shiny::withProgress(message = "Listing studies", {
      if (input$ref_mode == "trait") {
        shiny::validate(shiny::need(length(input$trait_pick), "Search and pick a trait first."))
        ot_studies(trait_ids = input$trait_pick, include_descendants = input$trait_descendants)
      } else {
        acc <- parse_accessions(input$accessions)
        shiny::validate(shiny::need(length(acc), "Paste at least one accession."))
        withCallingHandlers(ot_studies(accessions = acc), warning = function(w) {
          shiny::showNotification(conditionMessage(w), type = "warning", duration = 10)
          invokeRestart("muffleWarning")
        })
      }
    }))
    if (is.null(st)) return()
    rv$studies <- st
    yrs <- range(st$year, na.rm = TRUE)
    if (all(is.finite(yrs))) {
      shiny::updateSliderInput(session, "f_years", min = yrs[1], max = yrs[2], value = yrs)
    }
    pops <- sort(unique(unlist(strsplit(stats::na.omit(st$ancestries), ","))))
    shiny::updateCheckboxGroupInput(session, "f_ancestry", selected = character(),
                                    choices = stats::setNames(pops, ifelse(pops %in% names(ANCESTRY_LABELS),
                                                                           ANCESTRY_LABELS[pops], pops)))
    # accession lists are deliberate choices: do not filter them by kind
    if (input$ref_mode == "accession") {
      shiny::updateCheckboxGroupInput(session, "f_kinds", selected = names(KIND_LABELS))
    }
  })

  filtered <- shiny::reactive({
    shiny::req(rv$studies)
    lm_filter_studies(
      rv$studies, years = input$f_years,
      ancestry = if (length(input$f_ancestry)) input$f_ancestry,
      ancestry_match = input$f_anc_match, kinds = input$f_kinds,
      min_cases = if (isTRUE(input$f_min_cases > 0)) input$f_min_cases,
      require_credible_sets = input$f_need_cs
    )
  })

  output$study_status <- shiny::renderUI({
    if (input$ref_mode == "upload") {
      return(shiny::p("Upload credible sets and a study table, then press 'Use selected studies'."))
    }
    if (is.null(rv$studies)) {
      return(shiny::p("Search a trait or paste accessions, then press 'List studies'."))
    }
    shiny::span(class = "text-muted small", sprintf(
      "%d studies listed, %d pass the filters, %d selected. Click a row to leave it out or add it back.",
      nrow(rv$studies), nrow(filtered()), length(input$study_table_rows_selected)))
  })

  output$study_table <- DT::renderDT({
    f <- filtered()
    show <- f[, unname(STUDY_COLUMNS), with = FALSE]
    data.table::setnames(show, names(STUDY_COLUMNS))
    show[, Kind := KIND_SHORT[Kind]]
    show[, Ancestry := format_ancestry(Ancestry)]
    show[, Sumstats := data.table::fifelse(Sumstats, "yes", "no")]
    show[, Trait := ifelse(nchar(Trait) > 45, paste0(substr(Trait, 1, 44), "\u2026"), Trait)]
    show[, Accession := ifelse(grepl("^GCST", Accession),
      sprintf('<a href="https://www.ebi.ac.uk/gwas/studies/%s" target="_blank">%s</a>', Accession, Accession),
      Accession)]
    DT::datatable(show, escape = setdiff(names(show), "Accession"), rownames = FALSE,
                  class = "compact hover", selection = list(mode = "multiple", selected = seq_len(nrow(show))),
                  options = list(pageLength = 25, scrollX = TRUE, dom = "ftip",
                                 columnDefs = list(list(className = "dt-nowrap", targets = "_all"))))
  })
  table_proxy <- DT::dataTableProxy("study_table")
  shiny::observeEvent(input$sel_all, DT::selectRows(table_proxy, seq_len(nrow(filtered()))))
  shiny::observeEvent(input$sel_none, DT::selectRows(table_proxy, NULL))

  shiny::observeEvent(input$fetch, {
    if (input$ref_mode == "upload") {
      shiny::req(input$ref_cs, input$ref_studies)
      rv$ref <- notify_error(list(cs = lm_credible_sets(read_table_input(input$ref_cs)),
                                  studies = lm_studies(read_table_input(input$ref_studies)),
                                  cs_meta = NULL))
    } else {
      sel <- filtered()[input$study_table_rows_selected]
      if (!nrow(sel)) {
        shiny::showNotification("Select at least one study.", type = "warning")
        return()
      }
      rv$ref <- notify_error(shiny::withProgress(message = "Downloading credible sets", value = 0, {
        lm_reference_from_ot(sel, progress = function(done, total) shiny::setProgress(done / total))
      }))
    }
    if (!is.null(rv$ref)) {
      shiny::updateSelectInput(session, "query_study", choices = stats::setNames(
        rv$ref$studies$study_id, rv$ref$studies$label), selected = utils::tail(rv$ref$studies$study_id, 1))
      shiny::updateRadioButtons(session, "query_mode",
                                selected = if (input$ref_mode == "upload") "upload" else "ot")
      bslib::nav_select("navbar", "2. Your GWAS", session = session)
      shiny::showNotification(sprintf("Loaded %d credible sets from %d studies.",
                                      data.table::uniqueN(rv$ref$cs$cs_id), nrow(rv$ref$studies)))
    }
  })

  output$ref_summary <- shiny::renderUI({
    if (is.null(rv$ref)) return(shiny::p("No reference loaded yet: the demo uses simulated studies."))
    s <- rv$ref$studies
    methods <- if (!is.null(rv$ref$cs_meta)) rv$ref$cs_meta[, .N, by = method] else NULL
    shiny::tagList(
      shiny::p(sprintf("%d studies, %d credible sets, %s to %s.", nrow(s),
                       data.table::uniqueN(rv$ref$cs$cs_id), min(s$pub_date), max(s$pub_date))),
      if (!is.null(methods)) shiny::p(paste(sprintf("%s: %d", methods$method, methods$N), collapse = "; ")),
      if (!is.null(methods) && all(methods$method == "PICS")) shiny::p(class = "text-muted",
        "All credible sets come from reported top hits (PICS), so signals are compared through PIPs.")
    )
  })

  # ---- step 2-3: compare --------------------------------------------------------
  inputs <- shiny::eventReactive(input$run, ignoreNULL = FALSE, {
    if (input$query_mode == "demo") {
      ex <- lm_example
      return(list(cs = ex$cs, studies = ex$studies, sumstats = ex$sumstats,
                  blocks = lm_even_blocks(), reference_variants = ex$reference_variants,
                  query = ex$studies$study_id[nrow(ex$studies)], labels = NULL))
    }
    shiny::validate(shiny::need(rv$ref, "Load earlier studies in step 1 first."))
    blocks <- if (is.null(input$blocks)) lm_even_blocks() else lm_blocks(input$blocks$datapath)
    labels <- if (!is.null(rv$ref$cs_meta)) lm_labels_from_ot(rv$ref$cs_meta) else NULL
    sumstats <- read_table_input(input$query_sumstats)
    if (input$query_mode == "ot") {
      shiny::validate(shiny::need(input$query_study %in% rv$ref$cs$study_id,
                                  "The chosen study has no credible sets in the loaded reference."))
      return(list(cs = rv$ref$cs, studies = rv$ref$studies, sumstats = sumstats, blocks = blocks,
                  reference_variants = NULL, query = input$query_study, labels = labels))
    }
    shiny::validate(shiny::need(input$query_cs, "Upload your credible sets."))
    q <- read_table_input(input$query_cs)
    q[, `:=`(study_id = "query", cs_id = paste0("query:", cs_id))]
    if ("gene" %in% names(q)) {
      labels <- rbind(labels, unique(q[!is.na(gene) & gene != "", .(cs_id, label = gene)]))
    }
    studies <- rbind(rv$ref$studies, data.table::data.table(
      study_id = "query", pub_date = input$query_date, label = input$query_label), fill = TRUE)
    list(cs = rbind(rv$ref$cs, q, fill = TRUE), studies = studies, sumstats = sumstats,
         blocks = blocks, reference_variants = NULL, query = "query", labels = labels)
  })

  reg <- shiny::reactive({
    x <- inputs()
    shiny::withProgress(message = "Colocalising credible sets", {
      lm_build_registry(x$cs, x$studies, x$blocks, t_h4 = input$t_h4, t_h3 = input$t_h3,
                        reference_variants = x$reference_variants)
    })
  }) |> shiny::bindEvent(inputs(), input$run, ignoreNULL = FALSE)

  shiny::observeEvent(input$run, bslib::nav_select("navbar", "3. Signal map", session = session),
                      ignoreInit = TRUE)

  plot_args <- shiny::reactive(list(reg = reg(), query = inputs()$query,
                                    sumstats = inputs()$sumstats, labels = inputs()$labels,
                                    n_labels = 12))
  static_fig <- shiny::reactive(do.call(lm_plot_signal_map, plot_args()))

  output$summary <- shiny::renderUI({
    n <- reg()$calls[study_id == inputs()$query, .N, by = status]
    get <- function(s) if (s %in% n$status) n[status == s]$N else 0L
    shiny::p(shiny::HTML(sprintf(
      "<b>%d</b> signals: <b>%d</b> novel loci, <b>%d</b> new signals at known loci, <b>%d</b> known, <b>%d</b> ambiguous.",
      sum(n$N), get("novel_locus"), get("novel_signal"), get("replication"), get("ambiguous"))))
  })
  output$map <- ggiraph::renderGirafe(do.call(lm_plot_signal_map, c(plot_args(), interactive = TRUE)))
  calls_tab <- shiny::reactive({
    x <- reg()$calls[study_id == inputs()$query,
                     .(cs_id, signal_id, status, chrom, lead_pos, lead_variant, max_pip, n_variants,
                       lead_logp = round(lead_logp, 1), best_h4 = round(best_h4, 3), flags)]
    lab <- inputs()$labels
    if (!is.null(lab)) x <- merge(x, unique(lab, by = "cs_id")[, .(cs_id, gene = label)],
                                  by = "cs_id", all.x = TRUE)
    x
  })
  output$calls <- DT::renderDT(calls_tab(), rownames = FALSE,
                               options = list(pageLength = 15, scrollX = TRUE))
  output$signals <- DT::renderDT(reg()$signals, rownames = FALSE,
                                 options = list(pageLength = 15, scrollX = TRUE))

  save_fig <- function(device) function(file) {
    n_rows <- min(nrow(reg()$studies), 14)
    ggplot2::ggsave(file, static_fig(), width = 180, height = 70 + 3.2 * n_rows, units = "mm",
                    dpi = 300, device = device, bg = "white")
  }
  output$dl_png <- shiny::downloadHandler("locusmatch_signal_map.png", save_fig("png"))
  output$dl_pdf <- shiny::downloadHandler("locusmatch_signal_map.pdf", save_fig("pdf"))
  output$dl_calls <- shiny::downloadHandler("locusmatch_signals.tsv", function(file)
    data.table::fwrite(calls_tab(), file, sep = "\t"))
  output$dl_signals <- shiny::downloadHandler("locusmatch_registry.tsv", function(file)
    data.table::fwrite(reg()$signals, file, sep = "\t"))
}

HOW_TO_READ <- "
**a. Signals of this study.** Each marker is one fine-mapped credible set (one independent
association signal), placed at its lead variant. Orange: a locus where no earlier study
reported a signal. Blue diamond: a new, independent signal in a locus that was already
known. Grey: a signal that colocalises with one reported before. Hollow: not resolved.
Marker size is the posterior inclusion probability of the top variant, so large markers are
signals fine-mapped to few variants. The y-axis is square-root scaled so that the many
signals just past genome-wide significance remain legible.

**b. Discovery history.** One row per publication, oldest at the top (the smallest are pooled
in the first row). A tick marks every signal the publication reported, at the position of the
signal, so a column of ticks is a signal replicated across studies. Dark ticks: the
publication that first reported the signal.

**c. Cumulative discoveries.** Signals known after each publication: grey were already known,
the coloured part was added by that publication.

Two credible sets are the same signal when their colocalisation posterior H4 passes the
threshold (Bayes-factor coloc when both studies have log Bayes factors, the PIP-based
approximation otherwise). Signal IDs are tied to fixed LD blocks and never renamed.

**Reference data.** Credible sets of earlier studies come from the Open Targets Platform.
Studies that only published top hits are fine-mapped there with PICS; studies with full
summary statistics with SuSiE. Gene labels are Open Targets locus-to-gene predictions
(score of at least 0.5).
"
